function buildPredefinedStepsForTrades(
  trades: string[],
  defaultProjectManager = 'Direction de Projet'
): ProjectExecutionStep[] {
  const steps: ProjectExecutionStep[] = [];
  let counter = 1;
  trades.forEach((trade) => {
    const tradeSteps = PREDEFINED_STEPS_BY_TRADE[trade];
    if (tradeSteps && tradeSteps.length > 0) {
      tradeSteps.forEach((st) => {
        steps.push({
          phaseNumber: counter++,
          tradeName: trade,
          tradeLeaderName: `Chef Corps de Métier — ${trade}`,
          projectManagerName: defaultProjectManager,
          title: st.title,
          processDetails: st.processDetails,
          assignedTasks: st.processDetails,
          phaseObjectives: `Atteindre 100% de conformité sur : ${st.deliverable}`,
          duration: st.duration,
          deliverable: st.deliverable,
          progressPct: 0,
        });
      });
    } else {
      steps.push({
        phaseNumber: counter++,
        tradeName: trade,
        tradeLeaderName: `Chef Corps de Métier — ${trade}`,
        projectManagerName: defaultProjectManager,
        title: `Intervention & exécution — ${trade}`,
        processDetails: `Réalisation des travaux, contrôles techniques et livrables relevant du corps de métier ${trade}`,
        assignedTasks: `Exécution des ouvrages techniques, autocontrôles et coordination du lot ${trade}`,
        phaseObjectives: `Livraison sans réserve du lot ${trade} dans le délai imparti`,
        duration: '10 à 15 jours',
        deliverable: `PV de réception technique — ${trade}`,
        progressPct: 0,
      });
    }
  });
  return steps;
}

