  useEffect(() => {
    const handleGlobalCustomShortcut = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      if (
        target &&
        (target.tagName === 'INPUT' ||
          target.tagName === 'TEXTAREA' ||
          target.tagName === 'SELECT' ||
          target.isContentEditable)
      ) {
        return;
      }
      const combo = formatKeyboardEventCombo(event);
      if (!combo) return;
      const matched = userKeyboardShortcuts.find(
        (s) => s.currentCombo.toLowerCase() === combo.toLowerCase()
      );
      if (!matched) return;
      event.preventDefault();
      const action: ShortcutActionId = matched.id;
      if (action === 'goto_dashboard') setActiveTab('dashboard');
      else if (action === 'goto_projects') setActiveTab('projects');
      else if (action === 'goto_documents') setActiveTab('documents');
      else if (action === 'goto_attendance_qr') setActiveTab('attendance');
      else if (action === 'goto_payroll') setActiveTab('payroll');
      else if (action === 'goto_internal_chat') setActiveTab('twilio_hub');
      else if (action === 'goto_accounting') setActiveTab('accounting_fiscal');
      else if (action === 'goto_security_settings') setActiveTab('security');
      else if (action === 'open_letterhead') {
        setShowLetterheadStudioModal(true);
      } else if (action === 'new_pinned_note') {
        setActiveTab('dashboard');
        setDashboardNoteComposerTrigger((prev) => prev + 1);
      }
    };
    window.addEventListener('keydown', handleGlobalCustomShortcut);
    return () => window.removeEventListener('keydown', handleGlobalCustomShortcut);
  }, [userKeyboardShortcuts]);

