  // Real-time Project Profitability Distribution (Faible, Moyenne, Élevée) for PieChart in 'Projets'
  const realTimeProjectProfitabilityDistribution = useMemo(() => {
    const analyzedProjects = projects.map((p) => {
      const budget = Math.max(0, Number(p.budget) || 0);
      const projDocs = documents.filter(
        (d) =>
          (d.projectId === p.id || d.projectName === p.name) &&
          (d.docType === 'invoice' || d.status === 'paid' || d.status === 'invoiced')
      );
      const invoicedFromDocs = projDocs.reduce(
        (s, d) => s + (Number(d.totalAmount) || Number(d.subtotal) || 0),
        0
      );
      const revenueRef = Math.max(
        budget,
        Number(p.billedAmount) || 0,
        Number(p.invoicedAmount) || 0,
        invoicedFromDocs
      );

      // Real-time costs: stock movements out + purchase orders + payroll + direct spent
      const movCost = stockMovements
        .filter(
          (m) =>
            ((m as any).movementType === 'out' || (m as any).type === 'out') &&
            (m.projectId === p.id || m.projectName === p.name)
        )
        .reduce(
          (s, m) =>
            s +
            (Number((m as any).totalValue) ||
              (Number(m.quantity) || 0) * (Number((m as any).unitCost) || Number((m as any).unitPrice) || 0)),
          0
        );
      const poCost = purchaseOrders
        .filter((po) => po.projectId === p.id || po.projectName === p.name)
        .reduce((s, po) => s + (Number((po as any).totalAmount) || Number((po as any).amount) || 0), 0);
      const assignedEmpIds = new Set(
        employees
          .filter((e) => e.assignedProjectId === p.id || e.assignedProjectName === p.name)
          .map((e) => e.id)
      );
      const payrollCost = payslips
        .filter((ps) => assignedEmpIds.has(ps.employeeId))
        .reduce((s, ps) => s + (Number(ps.netSalary) || Number(ps.grossSalary) || 0), 0);

      const dynamicOperationalCost = movCost + poCost + payrollCost;
      const structuredSpent = Array.isArray(p.structuredSteps)
        ? p.structuredSteps.reduce(
            (s, st) => s + (Number((st as any).spentCost) || Number((st as any).actualCost) || 0),
            0
          )
        : 0;
      const realCost = Math.max(
        Number(p.spent) || 0,
        structuredSpent,
        dynamicOperationalCost
      );

      const effectiveRevenue = revenueRef > 0 ? revenueRef : Math.max(realCost * 1.2, 1);
      const netMarginAmount = effectiveRevenue - realCost;
      const marginPct = Number(((netMarginAmount / effectiveRevenue) * 100).toFixed(1));

      let category: 'high' | 'medium' | 'low' = 'medium';
      let categoryLabel = 'Rentabilité Moyenne (10% – 25%)';
      let shortLabel = 'Moyenne';
      let color = '#D97706';

      if (marginPct >= 25) {
        category = 'high';
        categoryLabel = 'Rentabilité Élevée (≥ 25%)';
        shortLabel = 'Élevée';
        color = '#059669';
      } else if (marginPct < 10) {
        category = 'low';
        categoryLabel = 'Rentabilité Faible (< 10%)';
        shortLabel = 'Faible';
        color = '#E11D48';
      }

      return {
        project: p,
        budget,
        effectiveRevenue,
        realCost,
        netMarginAmount,
        marginPct,
        category,
        categoryLabel,
        shortLabel,
        color,
      };
    });

    const highList = analyzedProjects.filter((x) => x.category === 'high');
    const mediumList = analyzedProjects.filter((x) => x.category === 'medium');
    const lowList = analyzedProjects.filter((x) => x.category === 'low');
    const totalCount = analyzedProjects.length;

    const pieSlices = [
      {
        id: 'high' as const,
        name: 'Rentabilité Élevée (≥ 25%)',
        shortName: 'Élevée',
        value: highList.length,
        percentage: totalCount > 0 ? Math.round((highList.length / totalCount) * 100) : 0,
        totalMargin: highList.reduce((s, x) => s + x.netMarginAmount, 0),
        avgMarginPct:
          highList.length > 0
            ? Number(
                (highList.reduce((s, x) => s + x.marginPct, 0) / highList.length).toFixed(1)
              )
            : 0,
        color: '#059669',
      },
      {
        id: 'medium' as const,
        name: 'Rentabilité Moyenne (10% - 25%)',
        shortName: 'Moyenne',
        value: mediumList.length,
        percentage: totalCount > 0 ? Math.round((mediumList.length / totalCount) * 100) : 0,
        totalMargin: mediumList.reduce((s, x) => s + x.netMarginAmount, 0),
        avgMarginPct:
          mediumList.length > 0
            ? Number(
                (mediumList.reduce((s, x) => s + x.marginPct, 0) / mediumList.length).toFixed(1)
              )
            : 0,
        color: '#D97706',
      },
      {
        id: 'low' as const,
        name: 'Rentabilité Faible (< 10%)',
        shortName: 'Faible',
        value: lowList.length,
        percentage: totalCount > 0 ? Math.round((lowList.length / totalCount) * 100) : 0,
        totalMargin: lowList.reduce((s, x) => s + x.netMarginAmount, 0),
        avgMarginPct:
          lowList.length > 0
            ? Number(
                (lowList.reduce((s, x) => s + x.marginPct, 0) / lowList.length).toFixed(1)
              )
            : 0,
        color: '#E11D48',
      },
    ];

    return {
      analyzedProjects,
      pieSlices,
      highCount: highList.length,
      mediumCount: mediumList.length,
      lowCount: lowList.length,
      totalCount,
    };
  }, [projects, documents, stockMovements, purchaseOrders, employees, payslips]);

  // Real-time J-7 Visual Reminder System for ongoing projects (7 days before dueDate)
  const ongoingProjectsDeadlineReminders = useMemo(() => {
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);

    return projects
      .filter(
        (p) =>
          p.status !== 'completed' &&
          p.achievementCategory !== 'completed_with_success' &&
          !p.isLocked &&
          (Number(p.progress) || 0) < 100
      )
      .map((p) => {
        const rawDue = p.dueDate || new Date().toISOString().slice(0, 10);
        const dueObj = new Date(`${rawDue.slice(0, 10)}T00:00:00`);
        const diffMs = dueObj.getTime() - todayStart.getTime();
        const daysRemaining = Number.isNaN(diffMs)
          ? 999
          : Math.ceil(diffMs / (1000 * 60 * 60 * 24));

        const isExactlyJMinus7 = daysRemaining === 7;
        const isWithin7DaysWindow = daysRemaining >= 0 && daysRemaining <= 7;
        const isOverdue = daysRemaining < 0;

        return {
          project: p,
          dueDate: rawDue.slice(0, 10),
          daysRemaining,
          isExactlyJMinus7,
          isWithin7DaysWindow,
          isOverdue,
          reminderAlertId: `al_j7_deadline_${p.id}_${rawDue.slice(0, 10)}`,
        };
      })
      .sort((a, b) => a.daysRemaining - b.daysRemaining);
  }, [projects]);

  // Automatically register visual reminder notifications in `alerts` state 7 days before due date of each ongoing project
  useEffect(() => {
    if (!activeTenantId || activeTenantId === 'default_tenant') return;
    const dueWithin7Days = ongoingProjectsDeadlineReminders.filter(
      (item) => item.isWithin7DaysWindow
    );
    if (dueWithin7Days.length === 0) return;

    setAlerts((prev) => {
      const existingIds = new Set(prev.map((a) => a.id));
      const newJ7Alerts: SmartAlertRecord[] = [];

      for (const item of dueWithin7Days) {
        if (!existingIds.has(item.reminderAlertId)) {
          const dayLabel =
            item.daysRemaining === 7
              ? 'J-7 EXACT (7 jours restants)'
              : item.daysRemaining === 0
                ? "AUJOURD'HUI (J-0)"
                : `J-${item.daysRemaining} (${item.daysRemaining} jour(s) restant(s))`;
          newJ7Alerts.push({
            id: item.reminderAlertId,
            ownerId: user?.uid || activeAccount?.id || 'local_owner',
            title: `[RAPPEL VISUEL J-7] Échéance Projet « ${item.project.name} » (${dayLabel})`,
            message: `Le projet en cours « ${item.project.name} » (Client : ${item.project.clientName}) arrive à échéance le ${item.dueDate} (${dayLabel}). Avancement actuel : ${item.project.progress || 0}%. Vérifiez les livrables et le cahier des charges.`,
            alertType: 'deadline',
            severity: item.daysRemaining <= 3 ? 'critical' : 'warning',
            dueDate: item.dueDate,
            isRead: false,
            pushEnabled: true,
            relatedDocId: item.project.id,
            recipientEmail: item.project.clientEmail || undefined,
          });
        }
      }

      if (newJ7Alerts.length === 0) return prev;
      return [...newJ7Alerts, ...prev];
    });
  }, [ongoingProjectsDeadlineReminders, activeTenantId, user, activeAccount]);

  // Configuration souveraine des Points d'Accès par Fonction, Module, Service et Fonctionnalité (définie par le Super-Admin)
