  // Compress and save uploaded company logo (< 140KB data URL)
  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
      const img = new Image();
      img.onload = async () => {
        const canvas = document.createElement('canvas');
        const maxDim = 220;
        let w = img.width;
        let h = img.height;
        if (w > maxDim || h > maxDim) {
          if (w > h) {
            h = Math.round((h * maxDim) / w);
            w = maxDim;
          } else {
            w = Math.round((w * maxDim) / h);
            h = maxDim;
          }
        }
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        ctx.drawImage(img, 0, 0, w, h);
        const dataUrl = canvas.toDataURL('image/png', 0.85);
        if (dataUrl.length > 145000) {
          triggerToast('Logo trop volumineux. Veuillez choisir une image plus simple.');
          return;
        }
        setCompanyLogo(dataUrl);
        localStorage.setItem(`mep_${activeTenantId}_logo`, dataUrl);
        const extractedHex = await extractBrandColorFromLogo(dataUrl);
        setDocCustomization((prev) => {
          const updated = { ...prev, headerHexColor: extractedHex };
          localStorage.setItem(`mep_${activeTenantId}_doc_custom`, JSON.stringify(updated));
          return updated;
        });
        if (user) {
          try {
            await updateDoc(doc(db, 'users', user.uid), {
              companyLogo: dataUrl,
              updatedAt: serverTimestamp(),
            });
          } catch (error) {
            handleFirestoreError(error, OperationType.UPDATE, `users/${user.uid}`);
          }
        }
        triggerToast(
          `Logo d'entreprise enregistré : papier en-tête et couleurs des documents (${extractedHex}) automatiquement harmonisés au logo.`
        );
      };
      if (typeof ev.target?.result === 'string') {
        img.src = ev.target.result;
      }
    };
    reader.readAsDataURL(file);
  };

