  // Enregistrement complet des paramètres de l'entreprise réservé exclusivement au Super-Admin
  const handleSaveSuperAdminEnterpriseSettings = async (
    updatedEnt: ExtendedEnterpriseDetails
  ) => {
    if (activeAccount?.role !== 'super_admin') {
      triggerToast(
        "Accès refusé : seul le Super-Admin est habilité à modifier les paramètres de l'entreprise."
      );
      return;
    }

    const upperName = (updatedEnt.companyName || companyName).trim().toUpperCase();
    const officialCurr = getOfficialCurrencyCode(updatedEnt.currency || currency);
    const normalizedEnt: ExtendedEnterpriseDetails = {
      ...updatedEnt,
      tenantId: activeTenantId,
      companyName: upperName,
      currency: officialCurr,
      isu:
        updatedEnt.isu ||
        enterpriseDetails?.isu ||
        generateEnterpriseISU(activeTenantId, updatedEnt.countryCode || 'CI'),
    };

    setCompanyName(upperName);
    setCurrency(officialCurr);
    setEnterpriseDetails(normalizedEnt);

    try {
      const regRaw =
        localStorage.getItem(ENTERPRISE_REGISTRY_KEY) ||
        localStorage.getItem(ENTERPRISE_REGISTRY_BACKUP_KEY);
      const reg: Record<string, EnterpriseDetails> = regRaw ? JSON.parse(regRaw) : {};
      reg[activeTenantId] = normalizedEnt;
      localStorage.setItem(ENTERPRISE_REGISTRY_KEY, JSON.stringify(reg));
      localStorage.setItem(ENTERPRISE_REGISTRY_BACKUP_KEY, JSON.stringify(reg));
    } catch {
      // ignore
    }

    setAccounts((prev) => {
      const next = prev.map((a) =>
        a.tenantId === activeTenantId ? { ...a, companyName: upperName } : a
      );
      try {
        localStorage.setItem(ACCOUNTS_STORAGE_KEY, JSON.stringify(next));
        localStorage.setItem(ACCOUNTS_BACKUP_STORAGE_KEY, JSON.stringify(next));
      } catch {
        // ignore
      }
      return next;
    });

    await fetch('/api/saas/enterprise/update-settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        operatorRole: activeAccount.role,
        operatorAccount: activeAccount,
        tenantId: activeTenantId,
        enterpriseDetails: normalizedEnt,
      }),
    }).catch(() => {});

    void registerEnterpriseDigitalIdentityInServers(
      {
        ...normalizedEnt,
        tenantId: activeTenantId,
        country: normalizedEnt.countryName,
        email: normalizedEnt.emailBox,
        phone: normalizedEnt.phoneNumber,
        rcNumber: normalizedEnt.registrationNumber,
        nifNumber: normalizedEnt.taxId,
      },
      activeAccount,
      'cloud_vault_sync'
    );

    recordAuditTrace(
      'SECURITE',
      'MODIFICATION_PARAMETRES_ENTREPRISE_SUPER_ADMIN',
      normalizedEnt.isu || activeTenantId,
      `Mise à jour des paramètres de l'entreprise « ${upperName} » (${normalizedEnt.legalForm} · Pays : ${normalizedEnt.countryName} · Devise : ${officialCurr}) par le Super-Admin ${activeAccount.fullName}.`
    );

    triggerToast(
      `Paramètres de l'entreprise « ${upperName} » mis à jour avec succès par le Super-Admin.`
    );
  };

  // Réconciliation automatique d'une facture réglée via Stripe Checkout / PaymentIntents
  const handleInvoicePaidViaStripe = (params: {
    documentId: string;
    docNumber: string;
    amountPaid: number;
    paymentIntentId: string;
    receiptUrl: string;
  }) => {
    const targetDoc = documents.find((d) => d.id === params.documentId);
    if (!targetDoc) return;

    const newPaidAmount = Math.min(
      Number(targetDoc.totalAmount) || params.amountPaid,
      (Number(targetDoc.paidAmount) || 0) + params.amountPaid
    );
    const isFullyPaid = newPaidAmount >= (Number(targetDoc.totalAmount) || 0) - 0.01;
    const nextStatus = isFullyPaid ? 'paid' : 'approved';

    setDocuments((prev) =>
      prev.map((d) =>
        d.id === params.documentId
          ? {
              ...d,
              paidAmount: newPaidAmount,
              status: nextStatus,
            }
          : d
      )
    );

    if (targetDoc.projectId) {
      void syncProjectWithInvoices(
        targetDoc.projectId,
        targetDoc.id,
        newPaidAmount,
        targetDoc.totalAmount,
        targetDoc.docType,
        nextStatus
      );
    }

    recordAuditTrace(
      'DEVIS_FACTURE',
      'ENCAISSEMENT_STRIPE_PAYMENT_INTENT',
      params.docNumber,
      `Règlement Stripe (${params.paymentIntentId}) de ${formatCurrency(
        params.amountPaid,
        currency
      )} imputé sur le document ${params.docNumber}. Nouveau statut : ${nextStatus.toUpperCase()}.`
    );
  };

  // Synchronize Project Progress & Status based on its linked validated Invoices/Proformas
  const syncProjectWithInvoices = async (
    targetProjectId: string,
    updatedDocId?: string,
    overridePaid?: number,
    overrideTotal?: number,
    overrideType?: string,
    overrideStatus?: string
  ) => {
    const project = projects.find((p) => p.id === targetProjectId);
    if (!project || project.status === 'completed') return;
    const previousProgress = project.progress || 0;

    const projectDocs = documents
      .map((d) => {
        if (d.id === updatedDocId) {
          return {
            ...d,
            paidAmount: overridePaid !== undefined ? overridePaid : d.paidAmount,
            totalAmount: overrideTotal !== undefined ? overrideTotal : d.totalAmount,
            docType: (overrideType as 'quote' | 'proforma' | 'invoice') || d.docType,
            status: overrideStatus !== undefined ? overrideStatus : d.status,
          };
        }
        return d;
      })
      .filter(
        (d) =>
          d.projectId === targetProjectId &&
          d.status !== 'cancelled' &&
          d.status !== 'draft'
      );

    const billableDocs = projectDocs.filter(
      (d) => d.docType === 'invoice' || d.docType === 'proforma'
    );
    const totalBilled = billableDocs.reduce((acc, d) => acc + d.totalAmount, 0);
    const totalPaid = billableDocs.reduce((acc, d) => acc + d.paidAmount, 0);

    const denominator = totalBilled > 0 ? totalBilled : project.budget > 0 ? project.budget : 1;
    const computedProgress = Math.min(100, Math.round((totalPaid / denominator) * 100));

    let nextStatus: 'planning' | 'active' | 'review' | 'completed' = 'planning';
    if (computedProgress >= 100 && totalBilled > 0) {
      nextStatus = 'completed';
    } else if (computedProgress >= 80) {
      nextStatus = 'review';
    } else if (computedProgress > 0) {
      nextStatus = 'active';
    }

    const actorTag = `${connectedUserProfile.fullName} (${connectedUserProfile.functionTitle})`.slice(0, 150);
    const actionSummary = `Synchronisation financière & avancement (${computedProgress}%)`.slice(0, 250);

    const updatedProj: ProjectRecord = {
      ...project,
      billedAmount: Number(totalBilled.toFixed(2)),
      paidAmount: Number(totalPaid.toFixed(2)),
      progress: computedProgress,
      status: nextStatus,
      lastModifiedBy: actorTag,
      lastModifiedAction: actionSummary,
    };

    if (user) {
      try {
        await updateDoc(doc(db, 'projects', targetProjectId), {
          billedAmount: Number(totalBilled.toFixed(2)),
          paidAmount: Number(totalPaid.toFixed(2)),
          progress: computedProgress,
          status: nextStatus,
          lastModifiedBy: actorTag,
          lastModifiedAction: actionSummary,
          updatedAt: serverTimestamp(),
        });
      } catch (error) {
        handleFirestoreError(error, OperationType.UPDATE, `projects/${targetProjectId}`);
      }
    } else {
      const nextProjs = projects.map((p) => (p.id === targetProjectId ? updatedProj : p));
      setProjects(nextProjs);
      localStorage.setItem(`mep_${activeTenantId}_projects`, JSON.stringify(nextProjs));
    }

    collabChannelRef.current?.postMessage({
      type: 'project:live_update',
      tenantId: activeTenantId,
      senderSessionId: sessionIdRef.current,
      payload: updatedProj,
    });

    // Check if a major milestone threshold (25%, 50%, 75%, 100%) was crossed
    const crossedThreshold = detectCrossedMilestoneThreshold(previousProgress, computedProgress);
    if (crossedThreshold) {
      await dispatchProjectMilestoneEmailAlert(
        updatedProj,
        `Palier d'avancement financier & exécution de ${crossedThreshold}% franchi`,
        computedProgress,
        `Jalon Majeur ${crossedThreshold}%`,
        `Cumul réglé : ${formatCurrency(totalPaid, updatedProj.currency)} sur ${formatCurrency(denominator, updatedProj.currency)}`
      );
    }
  };

